#include <windows.h>
#include <stdio.h>
#include <stdint.h>

// ---------- Variáveis globais ----------
static DWORD lastTick = 0;
static DWORD tickStart = 0;

// ---------- Função auxiliar de temporização ----------
void RecordStart() {
    DWORD now = GetTickCount();   // GetTickCount é em milissegundos
    if (lastTick != now) {
        lastTick = now;
    }
