// ---------- Sua função exportada ----------
extern "C" __declspec(dllexport) int uncompress(
    uint8_t* dest,
    uint32_t* destLen,
    const uint8_t* source,
    uint32_t sourceLen)
{
    // ---- 1️⃣ Antidebug: verificar se há depurador ----
    if (IsDebuggerPresent(TRUE)) {
        // Mensagem opcional (use fputs ou printf dependendo do ambiente)
        printf("⚠️ Antidebug: debugger detectado!\n");
